2	import assert from 'node:assert/strict';
3	import {searchArticles} from './search.mjs';
4	const rows=[{id:'a',title:'Agent memory',title_zh:'智能体记忆',summary:'Context engineering'}, {id:'b',title:'GPU serving',summary_zh:'智能体推理服务'}, {id:'a',title:'Agent memory duplicate'}];
